import{z as n,x as c,o as t,c as i,q as p,j as E,D as a,d as o,s as l,S as d,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"mprotect","description":"","frontmatter":{"title":"mprotect","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mprotect.md","filePath":"cs/mprotect.md","lastUpdated":1791413859000}'),m={name:"cs/mprotect.md"};function A(B,e,h,T,f,u){const s=c("Mermaid");return t(),i("div",null,[e[2]||(e[2]=p('<h1 id="mprotect" tabindex="-1">mprotect <a class="header-anchor" href="#mprotect" aria-label="Permalink to &quot;mprotect&quot;">​</a></h1><div class="epigraph"><p>已存在的虚区间可以改权限：读、写、执行的组合变了，页表项与 TLB 必须跟着变。</p><footer>—— 据 POSIX mprotect；Silberschatz 对保护域的整理</footer></div><p><a href="/cs/mmap">上一课</a>已经能把文件或匿名页接到 VMA。<a href="/cs/paging-vm">分页</a>的权限位在缺页时检查。<a href="/cs/user-kernel-split">用户/内核分裂</a>禁止用户给内核页加写。缺口是运行中<strong>改自己的用户页权限</strong>：JIT 要先写后执行，栈要 NX，调试器要临时可写。不是新的映射，是改已有映射。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若只能在 mmap 时定权限，代码生成器必须unmap 再 map，丢失内容或窗口不安全。<code>mprotect</code> 按页对齐改一段 VA 的 r/w/x。缺口：拆 VMA、改 PTE、<a href="/cs/tlb-shootdown">TLB shootdown</a>。把可写改成不可写可能触发后课 COW 已处理的逻辑；把不可执行改成可执行要受安全策略约束——本课只要求内核拒绝无意义组合，不讲攻击步骤。</p><p>本课不把 <code>pkey</code> 与内存保护键的全部 ISA 写完。</p><p><span class="marginnote"><code>madvise</code> 提示内核预读或可丢页，不改权限。<code>mincore</code> 查询哪些页在内存。本课合并：它们操作同一段 VMA，对象仍是区间，不是新的页表格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户给出区间与新 prot。内核按页对齐，必要时把原 VMA 劈成三段，中间段新权限。已存在的页改 PTE；未分配的页只改 VMA，下次<a href="/cs/page-fault-path">缺页路径</a>按新权限填。他核 TLB 必须 shootdown，否则仍按旧写位存储。失败返回 EACCES/ENOMEM，不留下半改的权限。</p><p><span class="marginnote">页对齐用数字看：4 KB 页、起始地址 \\(0x401023\\) 时，mprotect 实际作用的是从 \\(0x401000\\) 开始的整页——低 12 位被抹掉上取整。改一页只改了这 4096 字节，邻页权限原封不动，这就是要拆 VMA 的原因。</span></p>',10)),(t(),E(d,null,{default:a(()=>[l(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MP%5B%22mprotect%22%5D%20--%3E%20SPLIT%5B%22%E6%8B%86%E5%90%88%20VMA%22%5D%0A%20%20SPLIT%20--%3E%20PTE%5B%22%E6%94%B9%E5%B7%B2%E5%A1%AB%20PTE%22%5D%0A%20%20PTE%20--%3E%20SD%5B%22TLB%20shootdown%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r("h2",{id:"机制",tabindex:"-1"},[o("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=r("p",null,"mprotect 让保护变成动态的：同一物理页在不同时刻对同一进程可写或不可写。这与文件模式位不同——那是后课 inode 上的 rwx，对象是文件；这里是虚存。W^X 策略（写与执行不同时）由用户或安全模块在调用时拒绝，不是 MMU 新周期。",-1)),(t(),E(d,null,{default:a(()=>[l(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20JIT%5B%22JIT%20%E7%94%9F%E6%88%90%E6%9C%BA%E5%99%A8%E7%A0%81%22%5D%20--%3E%20W%5B%22%E9%98%B6%E6%AE%B5%E4%B8%80%3A%20mprotect%20RW%22%5D%0A%20%20W%20--%3E%20GEN%5B%22%E5%BE%80%E9%A1%B5%E9%87%8C%E5%86%99%E6%8C%87%E4%BB%A4%E5%AD%97%E8%8A%82%22%5D%0A%20%20GEN%20--%3E%20X%5B%22%E9%98%B6%E6%AE%B5%E4%BA%8C%3A%20mprotect%20RX%22%5D%0A%20%20X%20--%3E%20RUN%5B%22CPU%20%E6%89%A7%E8%A1%8C%E8%BF%99%E9%A1%B5%3A%20%E4%B8%8D%E5%8F%AF%E5%86%99%22%5D%0A%20%20RUN%20--%3E%20FIX%7B%22%E8%A6%81%E8%A1%A5%E5%86%99%E4%BB%A3%E7%A0%81%3F%22%7D%0A%20%20FIX%20--%3E%7C%22%E6%98%AF%22%7C%20W2%5B%22%E5%85%88%E6%94%B9%E5%9B%9E%20RW%20%E5%86%8D%E5%86%99%22%5D%0A%20%20W2%20--%3E%20X%0A%20%20FIX%20--%3E%7C%22%E5%90%A6%22%7C%20SAFE%5B%22%E6%B3%A8%E5%85%A5%E6%94%BB%E5%87%BB%E5%86%99%E4%B8%8D%E8%BF%9B%E8%BF%99%E9%A1%B5%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=p('<p><span class="marginnote">W^X 就是「同一页要么可写、要么可执行，永不同时」的纪律：写着的页不让 CPU 执行，执行中的页不让任何人改。JIT 被迫来回 mprotect 正是代价——每次切换都是一次系统调用加一轮 TLB 失效，所以 JIT 会攒一大批代码一次性切换。</span></p><p>不要重导页表 walker。只改权限位与 VMA 标志。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>userfaultfd</code> 与保护键的组合拳。不保证所有架构支持对文件共享映射随意加执行。区间必须页对齐；未对齐由内核上取整或报错，POSIX 有规定。下一课离开用户 VMA，问内核自己的物理页从哪来。</p><p><span class="marginnote">初学者容易把 mprotect 当成「内存版的 chmod」。实际上文件 rwx 管的是「谁能打开这个文件」，改的是 inode 元数据；mprotect 改的是 CPU 每次访存时硬件实时检查的页表权限位——一个是门禁名单，一个是车间里的急停闸，层级完全不同。</span></p><p>后课默认：用户可改已有映射的权限。内核分配 2^n 页块给页表与缓冲，下一课 buddy。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>mprotect 改 VMA 与 PTE 权限，并 shootdown。</li><li>未触碰的页只改区间描述，缺页时再生效。</li><li>内核页框分配器是 buddy 的缺口。</li><li>出处：POSIX.1 <code>mprotect</code>；Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>。</li></ul>',8))])}const D=n(m,[["render",A]]);export{_ as __pageData,D as default};
